insert into inventory_movements (product_id, quantity, from_entity_type, to_entity_type, to_entity_id, reason, created_by, notes, created_at)
select p.id,abs(round(si.amount::numeric))::int,'supplier','storage','00000000-0000-0000-0000-000000000201'::uuid,'purchase_received',tm.id,
coalesce(nullif(si.reason,''), 'Seeded opening balance') || ' | source inventory_id=' || si.inventory_id,si.datetime::timestamptz
from src_storage_inventory si
join products p on p.sku = si.item_id
left join team_members tm on tm.email = si.operator_email
where si.amount::numeric > 0;

commit;
